// The drift alarm: every JSON fixture (generated by the shell from the Rust
// command bodies) is checked against the contract's types here, so a shape
// change on either side fails `tsc`.
//
// Checked: every field the type requires is there with the right nesting,
// nullability and number-vs-string (Loose), and the JSON has no field the
// type lacks (Extra). Not checkable from a JSON import, which types "refresh"
// as string: literal values. tests/fixtures.spec.ts checks those at run time.
import type * as T from "./types";

import briefJson from "./fixtures/brief.json";
import errorsJson from "./fixtures/errors.json";
import funnelJson from "./fixtures/funnel.json";
import funnelNocrmJson from "./fixtures/funnel_nocrm.json";
import refreshEventsJson from "./fixtures/refresh_events.json";
import refreshEventsOtherJson from "./fixtures/refresh_events_other.json";
import refreshFinishedDegradedJson from "./fixtures/refresh_finished_degraded.json";
import refreshStateJson from "./fixtures/refresh_state.json";
import refreshStateRunningJson from "./fixtures/refresh_state_running.json";
import refreshStateWaitingJson from "./fixtures/refresh_state_waiting.json";
import reportJson from "./fixtures/report.json";
import reportDaysJson from "./fixtures/report_days.json";
import sessionJson from "./fixtures/session.json";
import sessionMarkersJson from "./fixtures/session_markers.json";
import sessionNewJson from "./fixtures/session_new.json";
import sessionsJson from "./fixtures/sessions.json";
import todayJson from "./fixtures/today.json";
import todayDegradedJson from "./fixtures/today_degraded.json";
import turnEventsJson from "./fixtures/turn_events.json";
import turnEventsOtherJson from "./fixtures/turn_events_other.json";
import workspaceJson from "./fixtures/workspace.json";

type Loose<V> = V extends string
  ? string
  : V extends readonly (infer U)[]
    ? Loose<U>[]
    : V extends object
      ? string extends keyof V
        ? { [k: string]: Loose<V[string]> | undefined } // a JSON array of maps types absent keys as undefined
        : { [K in keyof V]: Loose<V[K]> }
      : V;

type Keys<V> = V extends unknown ? keyof V : never;
type Field<V, K extends PropertyKey> = V extends unknown ? (K extends keyof V ? V[K] : never) : never;
type Arr<V> = Extract<V, readonly unknown[]>;
type Obj<V> = Exclude<Extract<V, object>, readonly unknown[]>;

/**
 * The paths the JSON has and the type does not (".day.numbers[].unit"): a
 * field the shell added. For a union the key may belong to any member.
 * A key typed only `undefined` is the array-of-maps artefact above.
 */
type Extra<J, V, P extends string = ""> = unknown extends V
  ? never
  : J extends readonly (infer E)[]
    ? Extra<E, Arr<V>[number], `${P}[]`>
    : J extends object
      ? {
          [K in keyof J & string]: [J[K]] extends [undefined]
            ? never
            : string extends Keys<Obj<V>>
              ? Extra<J[K], Field<Obj<V>, string>, `${P}.${K}`>
              : K extends Keys<Obj<V>>
                ? Extra<J[K], Field<Obj<V>, K>, `${P}.${K}`>
                : `${P}.${K}`;
        }[keyof J & string]
      : never;

const fixture =
  <V>() =>
  <J extends Loose<V>>(json: J & ([Extra<J, V>] extends [never] ? unknown : { "fields missing from types.ts": Extra<J, V> })) =>
    json as unknown as V;

